window.VO = [{"id":"s01","text":"Butter chicken was invented by Kundan Lal.","at":0.5,"t0":0.25,"t1":2.96},{"id":"s02","text":"There's just one problem. There were two of them.","at":6.62,"t0":3.31,"t1":5.84},{"id":"s03","text":"Kundan Lal Gujral, and Kundan Lal Jaggi. Two friends from Peshawar.","at":12.68,"t0":6.34,"t1":10.75},{"id":"s04","text":"Partition brought them to Delhi, where they ran one restaurant together: Moti Mahal.","at":22.8,"t0":11.4,"t1":16.23},{"id":"s05","text":"Its butter chicken got so famous, even Nehru came to eat.","at":33.36,"t0":16.68,"t1":20.265},{"id":"s06","text":"Today, their families run rival restaurants.","at":41.43,"t0":20.715,"t1":23.325},{"id":"s07","text":"And since twenty twenty-four, they've been in court over who invented butter chicken.","at":47.45,"t0":23.725,"t1":27.965},{"id":"s08","text":"The lawsuit is two thousand seven hundred and fifty-two pages long.","at":56.83,"t0":28.415,"t1":32.385},{"id":"s09","text":"The Gujrals say: Peshawar. Leftover chicken, saved in a gravy for the next day.","at":65.87,"t0":32.935,"t1":38.03},{"id":"s10","text":"The Jaggis say: Delhi. Late guests, and too little chicken.","at":77.06,"t0":38.53,"t1":41.985},{"id":"s11","text":"Too much chicken, or too little. Either way, the root cause was leftovers.","at":84.87,"t0":42.435,"t1":46.955},{"id":"s12","text":"Nearly three years on, the court still hasn't decided.","at":95.01,"t0":47.505,"t1":50.525},{"id":"s13","text":"But whoever wins, one thing is certain.","at":102.45,"t0":51.225,"t1":53.41},{"id":"s14","text":"Butter chicken was invented by Kundan Lal.","at":108.22,"t0":54.11,"t1":56.88}];
